655	/****************************************************************************
656	 * Private Functions - DMA Descriptor Management
657	 ****************************************************************************/
658	
659	static int alloc_dma(struct sg2000_eth_priv_s *priv)
660	{
661	  int i;
662	
663	  priv->tx_desc = kmm_memalign(16, TX_RING_SIZE *
664	                                sizeof(struct sg2000_dma_desc_s));
665	  priv->rx_desc = kmm_memalign(16, RX_RING_SIZE *
666	                                sizeof(struct sg2000_dma_desc_s));
667	
668	  if (!priv->tx_desc || !priv->rx_desc)
669	    {
670	      return -ENOMEM;
671	    }
672	
673	  memset(priv->tx_desc, 0, TX_RING_SIZE * sizeof(struct sg2000_dma_desc_s));
674	  memset(priv->rx_desc, 0, RX_RING_SIZE * sizeof(struct sg2000_dma_desc_s));
675	
676	  /* For MMU-less or identity-mapped platforms, virtual address = physical.
677	   * TODO: For strict MMU kernel builds, use mm_virt_to_phys().
678	   */
679	
680	  priv->tx_desc_phys = (uint32_t)(uintptr_t)priv->tx_desc;
681	  priv->rx_desc_phys = (uint32_t)(uintptr_t)priv->rx_desc;
682	
683	  for (i = 0; i < TX_RING_SIZE; i++)
684	    {
685	      priv->tx_buf[i] = kmm_memalign(4, TX_BUF_SIZE);
686	      if (!priv->tx_buf[i])
687	        {
688	          return -ENOMEM;
689	        }
690	
691	      priv->tx_pkt[i] = NULL;
692	    }
693	
694	  for (i = 0; i < RX_RING_SIZE; i++)
695	    {
696	      priv->rx_buf[i] = kmm_memalign(4, RX_BUF_SIZE);
697	      if (!priv->rx_buf[i])
698	        {
699	          return -ENOMEM;
700	        }
701	    }
702	
703	  return 0;
704	}
705	
706	static void init_desc_and_dma(struct sg2000_eth_priv_s *priv)
707	{
708	  uintptr_t base = priv->gmac_base;
709	  int i;
710	
711	  /* Initialize TX descriptors.
712	   * Mark the last descriptor with END_RING so DMA knows the ring boundary.
713	   */
714	
715	  for (i = 0; i < TX_RING_SIZE; i++)
716	    {
717	      priv->tx_desc[i].des0 = (i == TX_RING_SIZE - 1) ? TX_DESC_TER : 0;
718	      priv->tx_desc[i].des1 = 0;
719	      priv->tx_desc[i].des2 = (uint32_t)(uintptr_t)priv->tx_buf[i];
720	      priv->tx_desc[i].des3 = 0;
721	      priv->tx_pkt[i] = NULL;
722	    }
723	
724	  /* Initialize RX descriptors: set OWN=1 (DMA owns them, can write).
725	   * Mark the last descriptor with RER (RX End of Ring) in des1.
726	   */
727	
728	  for (i = 0; i < RX_RING_SIZE; i++)
729	    {
730	      priv->rx_desc[i].des0 = DESC_OWN;
731	      priv->rx_desc[i].des1 = RX_BUF_SIZE |
732	                              ((i == RX_RING_SIZE - 1) ? RX_DESC_RER : 0);
733	      priv->rx_desc[i].des2 = (uint32_t)(uintptr_t)priv->rx_buf[i];
734	      priv->rx_desc[i].des3 = 0;
735	    }
736	
737	  priv->tx_cur = 0;
738	  priv->tx_dirty = 0;
739	  priv->rx_cur = 0;
740	
741	  /* Configure DMA Bus Mode (CSR0): Fixed Burst, AAL, ATDS, USP, PBL=8 */
742	  putreg32(DMA_BUS_DEFAULT, base + DMA_BUS_MODE);
743	
744	  /* Configure AXI Bus Mode (CSR10): burst lengths + OSR limits */
745	  putreg32(DMA_AXI_DEFAULT, base + DMA_AXI_BUS_MODE);
746	
747	  /* Write descriptor ring base addresses */
748	  putreg32(priv->tx_desc_phys, base + DMA_TX_BASE_ADDR);
749	  putreg32(priv->rx_desc_phys, base + DMA_RCV_BASE_ADDR);
750	
751	  /* Mask all DMA interrupts via CSR7 (they are unmasked in start_mac_and_dma) */
752	  putreg32(0, base + DMA_INTR_ENA);
753	}
754	
755	/****************************************************************************
756	 * Private Functions - MAC and DMA Control
757	 ****************************************************************************/
758	
759	static void set_mac_addr(uintptr_t gmac_base, const uint8_t *mac)
760	{
761	  uint32_t hi;
762	  uint32_t lo;
763	
764	  hi = (mac[5] << 8) | mac[4] | GMAC_HI_REG_AE;
765	  lo = (mac[3] << 24) | (mac[2] << 16) | (mac[1] << 8) | mac[0];
766	
767	  putreg32(hi, gmac_base + GMAC_ADDR_HIGH(0));
768	  putreg32(lo, gmac_base + GMAC_ADDR_LOW(0));
769	}
770	
771	static void start_mac_and_dma(struct sg2000_eth_priv_s *priv)
772	{
773	  uintptr_t gmac_base = priv->gmac_base;
774	  uint32_t v;
775	
776	  /* Configure MAC based on PHY negotiation results */
777	
778	  v = GMAC_CORE_INIT;
779	  if (priv->speed == 100)
780	    {
781	      v |= GMAC_CONFIG_FES;   /* 100M */
782	    }
783	
784	  if (priv->duplex)
785	    {
786	      v |= GMAC_CONFIG_DM;    /* Full duplex */
787	    }
788	
789	  /* Enable MAC TX and RX */
790	  v |= GMAC_CONFIG_TE | GMAC_CONFIG_RE;
791	
792	  putreg32(v, gmac_base + GMAC_CONFIG);
793	
794	  /* Packet filter at correct DWMAC1000 offset (0x0004, not 0x0008).
795	   * Pass multicast + broadcast + unicast (promiscuous mode).
796	   */
797	
798	  putreg32(GMAC_FILTER_HMC | GMAC_FILTER_PM | GMAC_FILTER_PR,
799	           gmac_base + GMAC_FRAME_FILTER);
800	
801	  /* Enable MAC interrupts */
802	  putreg32(GMAC_INT_DEFAULT, gmac_base + GMAC_INT_MASK);
803	
804	  /* Enable DMA interrupts via CSR7 */
805	  putreg32(DMA_INTR_DEFAULT_MASK, gmac_base + DMA_INTR_ENA);
806	
807	  /* Start TX and RX DMA via CSR6 (single control register for DWMAC1000):
808	   * TSF (TX Store and Forward) + RSF (RX Store and Forward) +
809	   * OSF (Operate on Second Frame) + ST (Start TX) + SR (Start RX)
810	   */
811	
812	  putreg32(DMA_CONTROL_TSF | DMA_CONTROL_RSF | DMA_CONTROL_OSF |
813	           DMA_CONTROL_ST | DMA_CONTROL_SR,
814	           gmac_base + DMA_CONTROL);
815	}
816	
817	/****************************************************************************
818	 * Private Functions - Doorbell Helpers
819	 ****************************************************************************/
820	
821	static void tx_doorbell(struct sg2000_eth_priv_s *priv)
822	{
823	  /* DWMAC1000: write any value to DMA_XMT_POLL_DEMAND (CSR1) to trigger
824	   * the TX DMA engine to re-fetch descriptors from the TX descriptor ring.
825	   */
826	
827	  putreg32(1, priv->gmac_base + DMA_XMT_POLL_DEMAND);
828	}
829	
830	static void rx_doorbell(struct sg2000_eth_priv_s *priv)
831	{
832	  /* DWMAC1000: write any value to DMA_RCV_POLL_DEMAND (CSR2) to trigger
833	   * the RX DMA engine to re-fetch descriptors from the RX descriptor ring.
834	   */
835	
836	  putreg32(1, priv->gmac_base + DMA_RCV_POLL_DEMAND);
837	}
838	
839	/****************************************************************************
840	 * Private Functions - Hardware Transmit
841	 ****************************************************************************/
842	
843	static int hw_transmit(struct sg2000_eth_priv_s *priv,
844	                       const uint8_t *data, int len)
845	{
846	  unsigned int idx = priv->tx_cur;
847	  struct sg2000_dma_desc_s *desc = &priv->tx_desc[idx];
848	  irqstate_t flags;
849	  uint32_t csr5_before;
850	  uint32_t csr6;
851	
852	  /* Check if the ring is full */
853	
854	  if (desc->des0 & DESC_OWN)
855	    {
856	      return -EBUSY;
857	    }
858	
859	  /* Diagnostic: snapshot CSR5/CSR6 before TX submission */
860	
861	  csr5_before = getreg32(priv->gmac_base + DMA_STATUS);
862	  csr6 = getreg32(priv->gmac_base + DMA_CONTROL);
863	
864	  /* Copy data to DMA TX buffer */
865	
866	  memcpy(priv->tx_buf[idx], data, len);
867	
868	  desc->des2 = (uint32_t)(uintptr_t)priv->tx_buf[idx];
869	  desc->des1 = len;
870	
871	  /* OWN | First Segment | Last Segment | Interrupt on Completion.
872	   * Preserve TER (END_RING) bit if it was set during init.
873	   */
874	
875	  desc->des0 = DESC_OWN | TX_DESC_FS | TX_DESC_LS | TX_DESC_IC |
876	               (desc->des0 & TX_DESC_TER);
877	
878	  /* Diagnostic: dump TX descriptor and DMA state before doorbell */
879	
880	  syslog(LOG_INFO,
881	         "sg2000_eth: TX idx=%u len=%d\n"
882	         "  desc des0=0x%08" PRIX32 " des1=0x%08" PRIX32
883	         " des2=0x%08" PRIX32 " des3=0x%08" PRIX32 "\n"
884	         "  CSR5=0x%08" PRIX32 " CSR6=0x%08" PRIX32
885	         " TX_BASE=0x%08" PRIX32 " RX_BASE=0x%08" PRIX32 "\n"
886	         "  data[0..13]: %02x %02x %02x %02x %02x %02x"
887	         " %02x %02x %02x %02x %02x %02x %02x %02x\n",
888	         idx, len,
889	         desc->des0, desc->des1, desc->des2, desc->des3,
890	         csr5_before, csr6,
891	         getreg32(priv->gmac_base + DMA_TX_BASE_ADDR),
892	         getreg32(priv->gmac_base + DMA_RCV_BASE_ADDR),
893	         data[0], data[1], data[2], data[3], data[4], data[5],
894	         data[6], data[7], data[8], data[9], data[10], data[11],
895	         data[12], data[13]);
896	
897	  flags = up_irq_save();
898	  priv->tx_cur = (idx + 1) & (TX_RING_SIZE - 1);
899	
900	  /* Memory barrier: ensure descriptor is visible to DMA engine */
901	
902	  __asm__ volatile ("fence w,w" ::: "memory");
903	
904	  tx_doorbell(priv);
905	
906	  /* Verify DMA operation: poll descriptor OWN bit with timeout.
907	   * If DMA clears OWN, TX is working.  If OWN stays set, DMA is stuck.
908	   */
909	
910	  {
911	    int timeout = 10000;
912	    while ((desc->des0 & DESC_OWN) && --timeout > 0)
913	      {
914	        up_udelay(10);
915	      }
916	
917	    syslog(LOG_INFO,
918	           "sg2000_eth: TX complete check: OWN=%s timeout=%d "
919	           "CSR5=0x%08" PRIX32 "\n",
920	           (desc->des0 & DESC_OWN) ? "STILL_SET(DMA_STUCK)" : "CLEARED(OK)",
921	           10000 - timeout,
922	           getreg32(priv->gmac_base + DMA_STATUS));
923	  }
924	
925	  up_irq_restore(flags);
926	
927	  return 0;
928	}
929	
930	/****************************************************************************
931	 * Private Functions - TX Cleanup (called from ISR on TX complete)
932	 ****************************************************************************/
933	
934	static void tx_cleanup(struct sg2000_eth_priv_s *priv)
935	{
936	  irqstate_t flags = up_irq_save();
937	
938	  while (priv->tx_dirty != priv->tx_cur)
939	    {
940	      struct sg2000_dma_desc_s *desc = &priv->tx_desc[priv->tx_dirty];
941	
942	      if (desc->des0 & DESC_OWN)
943	        {
944	          /* Still owned by DMA, stop */
945	
946	          break;
947	        }
948	
949	      /* Free the netpkt if we have one tracked for this slot */
950	
951	      if (priv->tx_pkt[priv->tx_dirty] != NULL)
952	        {
953	          netpkt_free(&priv->dev, priv->tx_pkt[priv->tx_dirty], NETPKT_TX);
954	          priv->tx_pkt[priv->tx_dirty] = NULL;
955	
956	          /* Notify upper half that TX is done */
957	
958	          netdev_lower_txdone(&priv->dev);
959	        }
960	
961	      /* Move to next descriptor */
962	
963	      priv->tx_dirty = (priv->tx_dirty + 1) & (TX_RING_SIZE - 1);
964	    }
965	
966	  up_irq_restore(flags);
967	}
968	
969	/****************************************************************************
970	 * Private Functions - ISR
971	 ****************************************************************************/
972	
973	static int sg2000_eth_isr(int irq, void *context, void *arg)
974	{
975	  struct sg2000_eth_priv_s *priv = (struct sg2000_eth_priv_s *)arg;
976	  uintptr_t base = priv->gmac_base;
977	  uint32_t status;
978	  uint32_t mac;
979	
980	  /* Clear MAC interrupts */
981	
982	  mac = getreg32(base + GMAC_INT_STATUS);
983	  if (mac)
984	    {
985	      putreg32(mac, base + GMAC_INT_STATUS);
986	    }
987	
988	  /* Read DMA Status (CSR5 at 0x1014) */
989	
990	  status = getreg32(base + DMA_STATUS);
991	
992	  if (!status)
993	    {
994	      return OK;
995	    }
996	
997	  /* Write-1-to-clear the status bits (CSR5 bits 0-16 are W1C) */
998	
999	  putreg32(status & DMA_STATUS_W1C_MASK, base + DMA_STATUS);
1000	
1001	  if (status & DMA_STATUS_NIS)
1002	    {
1003	      /* Normal interrupt */
1004	
1005	      if (status & DMA_STATUS_RI)
1006	        {
1007	          /* RX complete: notify upper half */
1008	          netdev_lower_rxready(&priv->dev);
1009	        }
1010	
1011	      if (status & DMA_STATUS_TI)
1012	        {
1013	          /* TX complete: cleanup descriptors */
1014	          tx_cleanup(priv);
1015	        }
1016	    }
1017	
1018	  if (status & DMA_STATUS_AIS)
1019	    {
1020	      /* Abnormal interrupt - handled silently in ISR context */
1021	    }
1022	
1023	  return OK;
1024	}
