{
  uint32_t hw_feat = getreg32(base + DMA_HW_FEATURE);

  syslog(LOG_INFO,
         "sg2000_eth: DMA_HW_FEATURE=0x%08" PRIX32 "\n", hw_feat);

  if (hw_feat & DMA_HW_FEATURE_TSEN)
    {
      /* Timestamp engine is present — make sure it stays off so
       * ATDS=1 produces 16-byte enhanced descriptors, not 32-byte
       * extended ones.
       */

      uint32_t ts_ctrl = getreg32(base + GMAC_TIMESTAMP_CTRL);

      if (ts_ctrl & GMAC_TS_TSENA)
