503	/****************************************************************************
504	 * Name: eth_input
505	 *
506	 * Description:
507	 *   Handle L2 packet input.
508	 *
509	 * Input Parameters:
510	 *   dev - Reference to the NuttX network driver state structure
511	 *
512	 * Assumptions:
513	 *   Called with the network locked.
514	 *
515	 ****************************************************************************/
516	
517	#if defined(CONFIG_NET_LOOPBACK) || defined(CONFIG_NET_ETHERNET) || \
518	    defined(CONFIG_DRIVERS_IEEE80211)
519	static void eth_input(FAR struct net_driver_s *dev)
520	{
521	  FAR struct eth_hdr_s *eth_hdr = (FAR struct eth_hdr_s *)NETLLBUF;
522	
523	  /* Check if this is an 802.1Q VLAN tagged packet */
524	
525	#ifdef CONFIG_NET_VLAN
526	  if (eth_hdr->type == HTONS(ETHERTYPE_VLAN))
527	    {
528	      FAR struct netdev_upperhalf_s *upper = dev->d_private;
529	      FAR struct netdev_lowerhalf_s *vlan;
530	      FAR struct eth_8021qhdr_s *vlan_hdr = NETLLBUF;
531	      uint16_t vid = NTOHS(vlan_hdr->tci) & VLAN_VID_MASK;
532	
533	      vlan = netdev_upper_vlan_dev(upper, vid);
534	      if (vlan)
535	        {
536	          /* Need to remove the 4 octet VLAN Tag, by moving src and dest
537	           * addresses 4 octets to the right, and then read the actual
538	           * ethertype.
539	           */
540	
541	          netdev_lock(&vlan->netdev);
542	          memmove((FAR uint8_t *)eth_hdr + 4, eth_hdr,
543	                  offsetof(struct eth_hdr_s, type));
544	          netdev_iob_release(&vlan->netdev);
545	          vlan->netdev.d_iob = iob_trimhead(dev->d_iob, 4);
546	          vlan->netdev.d_len = dev->d_len - 4;
547	          netdev_iob_clear(dev);
548	
549	          /* Then call eth_input again with the new dev */
550	
551	#ifdef CONFIG_NET_PKT
552	          pkt_input(&vlan->netdev);
553	#endif
554	          eth_input(&vlan->netdev);
555	          netdev_unlock(&vlan->netdev);
556	        }
557	      else
558	        {
559	          ninfo("INFO: Dropped, unknown vlan id: %d\n", vid);
560	          NETDEV_RXDROPPED(dev);
561	          dev->d_len = 0;
562	        }
563	    }
564	  else
565	#endif
566	
567	  /* We only accept IP packets of the configured type and ARP packets */
568	
569	#ifdef CONFIG_NET_IPv4
570	  if (eth_hdr->type == HTONS(ETHTYPE_IP))
571	    {
572	      ninfo("IPv4 frame\n");
573	      NETDEV_RXIPV4(dev);
574	
575	      /* Receive an IPv4 packet from the network device */
576	
577	      ipv4_input(dev);
578	    }
579	  else
580	#endif
581	#ifdef CONFIG_NET_IPv6
582	  if (eth_hdr->type == HTONS(ETHTYPE_IP6))
583	    {
584	      ninfo("IPv6 frame\n");
585	      NETDEV_RXIPV6(dev);
586	
587	      /* Give the IPv6 packet to the network layer */
588	
589	      ipv6_input(dev);
590	    }
591	  else
592	#endif
593	#ifdef CONFIG_NET_ARP
594	  if (eth_hdr->type == HTONS(ETHTYPE_ARP))
595	    {
596	      ninfo("ARP frame\n");
597	      NETDEV_RXARP(dev);
598	
599	      /* Handle ARP packet */
600	
601	      arp_input(dev);
602	    }
603	  else
604	#endif
605	    {
606	      ninfo("INFO: Dropped, Unknown type: %04x\n", eth_hdr->type);
607	      NETDEV_RXDROPPED(dev);
608	      dev->d_len = 0;
609	      netdev_iob_release(dev);
610	    }
611	
612	  /* If the above function invocation resulted in data
613	   * that should be sent out on the network,
614	   * the field d_len will set to a value > 0.
615	   */
616	
617	  if (dev->d_len > 0)
618	    {
619	      /* And queue the packet for sending later.
620	       * Note: RX is tried before TX, so we don't need to call txavail here.
621	       */
622	
623	      netdev_upper_queue_tx(dev);
624	    }
625	}
626	#endif
