1061	                  {
1062	                    nerr("ERROR: Failed to connect\n");
1063	                    break;
1064	                  }
1065	              }
1066	            else
1067	              {
1068	                ret = ops->disconnect(lower);
1069	                if (ret < 0)
1070	                  {
1071	                    nerr("ERROR: Failed to disconnect\n");
1072	                    break;
1073	                  }
1074	              }
1075	          }
1076	        break;
1077	
1078	      case SIOCGIWAP: /* Get access point MAC addresses */
1079	        if (ops->bssid)
1080	          {
1081	            ret = ops->bssid(lower, iwr, false);
1082	          }
1083	        break;
1084	
1085	      case SIOCSIWSCAN: /* Trigger scanning */
1086	        if (ops->scan)
1087	          {
1088	            ret = ops->scan(lower, iwr, true);
1089	          }
1090	        break;
1091	
1092	      case SIOCGIWSCAN: /* Get scanning results */
1093	        if (ops->scan)
1094	          {
1095	            ret = ops->scan(lower, iwr, false);
1096	          }
1097	        break;
1098	
1099	      case SIOCSIWCOUNTRY: /* Set country code */
1100	        if (ops->country)
1101	          {
1102	            ret = ops->country(lower, iwr, true);
1103	          }
1104	        break;
1105	
1106	      case SIOCGIWCOUNTRY: /* Get country code */
1107	        if (ops->country)
1108	          {
1109	            ret = ops->country(lower, iwr, false);
1110	          }
1111	        break;
1112	
1113	      case SIOCSIWSENS: /* Set sensitivity (dBm) */
1114	        if (ops->sensitivity)
1115	          {
1116	            ret = ops->sensitivity(lower, iwr, true);
1117	          }
1118	        break;
1119	
1120	      case SIOCGIWSENS: /* Get sensitivity (dBm) */
