1122	          {
1123	            ret = ops->sensitivity(lower, iwr, false);
1124	          }
1125	        break;
1126	
1127	      case SIOCSIWMODE: /* Set operation mode */
1128	        if (ops->mode)
1129	          {
1130	            ret = ops->mode(lower, iwr, true);
1131	          }
