1247	/****************************************************************************
1248	 * Name: netdev_upper_exit_thread
1249	 *
1250	 * Description:
1251	 *   Exit the dedicated thread
1252	 *
1253	 ****************************************************************************/
1254	
1255	static void netdev_upper_exit_thread(FAR struct netdev_upperhalf_s *upper)
1256	{
1257	  int cpu = 1;
1258	
1259	  switch (upper->lower->rxtype)
1260	    {
1261	      case NETDEV_RX_THREAD_RSS:
1262	        cpu = CONFIG_SMP_NCPUS;
1263	      case NETDEV_RX_THREAD:
1264	        while (--cpu >= 0)
1265	          {
1266	            FAR struct netdev_thread_s *t = &upper->thread[cpu];
1267	
1268	            if (t->tid >= 0)
1269	              {
1270	                /* Try to tear down the dedicated thread for work. */
1271	
1272	                t->tid = INVALID_PROCESS_ID;
1273	                nxsem_post(&t->sem);
1274	                nxsem_wait(&t->sem_exit);
1275	              }
1276	          }
1277	        break;
1278	    }
1279	}
1280	
1281	/****************************************************************************
1282	 * Name: netdev_upper_ifup/ifdown/addmac/rmmac/ioctl
1283	 *
1284	 * Description:
1285	 *   Called by net stack and relayed to lower half driver.
1286	 *
1287	 ****************************************************************************/
1288	
1289	static int netdev_upper_ifup(FAR struct net_driver_s *dev)
1290	{
1291	  FAR struct netdev_upperhalf_s *upper = dev->d_private;
1292	  int cpu = 1;
1293	
1294	  switch (upper->lower->rxtype)
1295	    {
1296	      case NETDEV_RX_THREAD_RSS:
1297	        cpu = CONFIG_SMP_NCPUS;
1298	      case NETDEV_RX_THREAD:
1299	
1300	        /* Try to bring up a dedicated thread for work. */
1301	
1302	        while (--cpu >= 0)
1303	          {
1304	            FAR struct netdev_thread_s *t = &upper->thread[cpu];
1305	            FAR char *argv[3];
1306	            char      arg1[32];
1307	            char      arg2[32];
1308	            char      name[32];
1309	
1310	            snprintf(arg1, sizeof(arg1), "%p", upper);
1311	            argv[0] = arg1;
1312	
1313	            snprintf(arg2, sizeof(arg2), "%d", cpu);
1314	            argv[1] = arg2;
1315	            argv[2] = NULL;
1316	
1317	            snprintf(name, sizeof(name), NETDEV_THREAD_NAME_FMT,
1318	                     dev->d_ifname);
1319	
1320	            t->tid = kthread_create(name, upper->lower->priority,
1321	                                    CONFIG_DEFAULT_TASK_STACKSIZE,
1322	                                    netdev_upper_loop, argv);
1323	            if (t->tid < 0)
1324	              {
1325	                netdev_upper_exit_thread(upper);
1326	                return t->tid;
1327	              }
1328	          }
1329	        break;
1330	    }
1331	
1332	  if (upper->lower->ops->ifup)
1333	    {
1334	      return upper->lower->ops->ifup(upper->lower);
1335	    }
1336	
1337	  return -ENOSYS;
1338	}
1339	
1340	static int netdev_upper_ifdown(FAR struct net_driver_s *dev)
1341	{
1342	  FAR struct netdev_upperhalf_s *upper = dev->d_private;
1343	
1344	  switch (upper->lower->rxtype)
1345	    {
1346	      case NETDEV_RX_WORK:
1347	        work_cancel_sync(upper->lower->priority, upper->work);
1348	        break;
1349	      case NETDEV_RX_THREAD:
1350	      case NETDEV_RX_THREAD_RSS:
1351	        netdev_upper_exit_thread(upper);
1352	        break;
1353	    }
1354	
1355	  if (upper->lower->ops->ifdown)
1356	    {
1357	      return upper->lower->ops->ifdown(upper->lower);
1358	    }
1359	
1360	  return -ENOSYS;
1361	}
1362	
