1440	/****************************************************************************
1441	 * Name: netdev_lower_register
1442	 *
1443	 * Description:
1444	 *   Register a network device driver and assign a name to it so that it can
1445	 *   be found in subsequent network ioctl operations on the device.
1446	 *
1447	 * Input Parameters:
1448	 *   dev    - The lower half device driver structure to be registered.
1449	 *   lltype - Link level protocol used by the driver (Ethernet, SLIP, TUN,
1450	 *            ...
1451	 *
1452	 * Returned Value:
1453	 *   0:Success; negated errno on failure.
1454	 *
1455	 ****************************************************************************/
1456	
1457	int netdev_lower_register(FAR struct netdev_lowerhalf_s *dev,
1458	                          enum net_lltype_e lltype)
1459	{
1460	  FAR struct netdev_upperhalf_s *upper;
1461	  size_t extra_size;
1462	  int cpu = 0;
1463	  int ret;
1464	
1465	  if (dev == NULL || dev->ops == NULL ||
1466	      dev->ops->transmit == NULL || dev->ops->receive == NULL)
1467	    {
1468	      nerr("ERROR: Invalid lower half device\n");
1469	      return -EINVAL;
1470	    }
1471	
1472	  if (dev->quota_ptr == NULL)
1473	    {
1474	      dev->quota_ptr = dev->quota;
1475	    }
1476	
1477	  if (quota_is_valid(dev) == false)
1478	    {
1479	      return -EINVAL;
1480	    }
1481	
1482	  switch (dev->rxtype)
1483	    {
1484	      case NETDEV_RX_WORK:
1485	        extra_size = sizeof(struct work_s);
1486	        break;
1487	      case NETDEV_RX_DIRECT:
1488	        extra_size = 0; /* No extra size needed for direct mode */
1489	        break;
1490	      case NETDEV_RX_THREAD:
1491	        extra_size = sizeof(struct netdev_thread_s);
1492	        cpu = 1;
1493	        break;
1494	      case NETDEV_RX_THREAD_RSS:
1495	        extra_size = sizeof(struct netdev_thread_s) * CONFIG_SMP_NCPUS;
1496	        cpu = CONFIG_SMP_NCPUS;
1497	        break;
1498	      default:
1499	        nerr("ERROR: Unrecognized device rxtype: %d\n", dev->rxtype);
1500	        return -EINVAL;
1501	    }
1502	
1503	  if ((upper = netdev_upper_alloc(dev, extra_size)) == NULL)
1504	    {
1505	      return -ENOMEM;
1506	    }
1507	
1508	  upper->txing = false;
1509	
1510	  dev->netdev.d_ifup    = netdev_upper_ifup;
1511	  dev->netdev.d_ifdown  = netdev_upper_ifdown;
1512	  dev->netdev.d_txavail = netdev_upper_txavail;
1513	#ifdef CONFIG_NET_MCASTGROUP
1514	  dev->netdev.d_addmac  = netdev_upper_addmac;
1515	  dev->netdev.d_rmmac   = netdev_upper_rmmac;
1516	#endif
1517	#ifdef CONFIG_NETDEV_IOCTL
1518	  dev->netdev.d_ioctl   = netdev_upper_ioctl;
1519	#endif
1520	  dev->netdev.d_private = upper;
1521	
1522	  ret = netdev_register(&dev->netdev, lltype);
1523	  if (ret < 0)
1524	    {
1525	      nerr("ERROR: Netdev_register failed: %d\n", ret);
1526	      kmm_free(upper);
1527	      dev->netdev.d_private = NULL;
1528	    }
1529	
1530	  while (--cpu >= 0)
1531	    {
1532	      FAR struct netdev_thread_s *t = &upper->thread[cpu];
1533	
1534	      t->tid = INVALID_PROCESS_ID;
1535	      nxsem_init(&t->sem, 0, 0);
1536	      nxsem_init(&t->sem_exit, 0, 0);
1537	    }
1538	
1539	  return ret;
1540	}
1541	
1542	/****************************************************************************
1543	 * Name: netdev_lower_unregister
1544	 *
1545	 * Description:
1546	 *   Unregister a network device driver.
1547	 *
1548	 * Input Parameters:
1549	 *   dev - The lower half device driver structure to un-register
1550	 *
1551	 * Returned Value:
1552	 *   0:Success; negated errno on failure
1553	 *
1554	 ****************************************************************************/
1555	
1556	int netdev_lower_unregister(FAR struct netdev_lowerhalf_s *dev)
1557	{
1558	  FAR struct netdev_upperhalf_s *upper;
1559	  int cpu = 1;
1560	  int ret;
1561	
1562	  if (dev == NULL || dev->netdev.d_private == NULL)
1563	    {
1564	      nerr("ERROR: Invalid lower half device\n");
1565	      return -EINVAL;
1566	    }
1567	
1568	  upper = (FAR struct netdev_upperhalf_s *)dev->netdev.d_private;
1569	
1570	#ifdef CONFIG_NET_VLAN
1571	  netdev_upper_vlan_foreach(upper, vlan_unregister);
1572	#endif
1573	
1574	  ret = netdev_unregister(&dev->netdev);
1575	  if (ret < 0)
1576	    {
1577	      return ret;
1578	    }
1579	
1580	  switch (dev->rxtype)
1581	    {
1582	      case NETDEV_RX_THREAD_RSS:
1583	        cpu = CONFIG_SMP_NCPUS;
1584	      case NETDEV_RX_THREAD:
1585	        netdev_upper_exit_thread(upper);
1586	        while (--cpu >= 0)
1587	          {
1588	            FAR struct netdev_thread_s *t = &upper->thread[cpu];
1589	
1590	            nxsem_destroy(&t->sem);
1591	            nxsem_destroy(&t->sem_exit);
1592	          }
1593	        break;
1594	    }
1595	
1596	#if CONFIG_IOB_NCHAINS > 0
1597	  iob_free_queue(&upper->txq);
1598	#endif
1599	
1600	  kmm_free(upper);
1601	  dev->netdev.d_private = NULL;
1602	
1603	  return OK;
1604	}
