1809	/****************************************************************************
1810	 * Name: netpkt_alloc
1811	 *
1812	 * Description:
1813	 *   Allocate a netpkt structure.
1814	 *
1815	 * Input Parameters:
1816	 *   dev  - The lower half device driver structure
1817	 *   type - Whether used for TX or RX
1818	 *
1819	 * Returned Value:
1820	 *   Pointer to the packet, NULL on failure
1821	 *
1822	 ****************************************************************************/
1823	
1824	FAR netpkt_t *netpkt_alloc(FAR struct netdev_lowerhalf_s *dev,
1825	                           enum netpkt_type_e type)
1826	{
1827	  FAR netpkt_t *pkt;
1828	
1829	  if (atomic_sub(&dev->quota_ptr[type], 1) <= 0)
1830	    {
1831	      atomic_add(&dev->quota_ptr[type], 1);
1832	      return NULL;
1833	    }
1834	
1835	#ifdef CONFIG_NET_CAN
1836	  if (dev->netdev.d_lltype == NET_LL_CAN)
1837	    {
1838	      pkt = can_iob_timedalloc(0);
1839	    }
1840	  else
1841	#endif
1842	    {
1843	      pkt = iob_tryalloc(false);
1844	    }
1845	
1846	  if (pkt == NULL)
1847	    {
1848	      atomic_add(&dev->quota_ptr[type], 1);
1849	      return NULL;
1850	    }
1851	
1852	  iob_reserve(pkt, CONFIG_NET_LL_GUARDSIZE);
1853	  return pkt;
1854	}
